static Vector2[] line={new Vector2(671.335f,-498.224f),new Vector2(732.523f,-413.958f),new Vector2(750.081f,-336.064f),new Vector2(779.848f,-267.728f),new Vector2(821.046f,-139.529f),new Vector2(838.937f,200.300f),new Vector2(831.177f,440.990f),new Vector2(799.858f,549.559f),new Vector2(740.518f,611.861f),new Vector2(609.973f,626.362f),new Vector2(491.038f,628.735f),new Vector2(390.337f,628.623f),new Vector2(289.087f,613.423f)};
static Dictionary<Vector2Int,float> foundation=new Dictionary<Vector2Int,float>();static List<Vector2[]> quads=new List<Vector2[]>();static Dictionary<Vector2Int,float> roadHeight=new Dictionary<Vector2Int,float>();const float width=45;
static CoastalTerrainScope(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalTerrainScope.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("CoastalTerrainScope.request");Run();}
static float Cross(Vector2 a,Vector2 b,Vector2 p)=>(b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x);
static bool In(Vector2 p,Vector2[] q){for(int i=0;i<q.Length;i++)if(Cross(q[i],q[(i+1)%q.Length],p)<0)return false;return true;}
static bool MaskGeo(float x,float z)=>quads.Any(q=>In(new Vector2(x,z),q));static bool Mask(float x,float z)=>MaskGeo(x,z)&&foundation.ContainsKey(new Vector2Int(Mathf.RoundToInt(x/2),Mathf.RoundToInt(z/2)));
static float D(float x,float z,out float along){var p=new Vector2(x,z);float d=float.MaxValue;along=0;float length=0;for(int i=0;i<line.Length-1;i++){var e=line[i+1]-line[i];float t=Mathf.Clamp01(Vector2.Dot(p-line[i],e)/e.sqrMagnitude);float v=Vector2.Distance(p,line[i]+e*t);if(v<d){d=v;along=length+t*e.magnitude;}length+=e.magnitude;}return d;}
static float H(float x,float z){if(!Mask(x,z))return 27.45f;float d=D(x,z,out float along);float total=0;for(int i=0;i<line.Length-1;i++)total+=Vector2.Distance(line[i],line[i+1]);float end=Mathf.SmoothStep(0,1,Mathf.Min(along,total-along)/45);float rise=Mathf.SmoothStep(0,1,Mathf.InverseLerp(8,33,d));float fall=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(34,45,d));float broad=Mathf.PerlinNoise(x/75+13,z/75+21);float ridge=1-Mathf.Abs(Mathf.PerlinNoise(x/19+31,z/19+17)*2-1);float foothill=3*Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,9,d));float crag=(1-Mathf.Abs(Mathf.PerlinNoise(x/7+71,z/7+43)*2-1)-.5f)*5;float peak=(foothill+(10+broad*19+ridge*7+crag)*rise)*fall*end;float h=foundation[new Vector2Int(Mathf.RoundToInt(x/2),Mathf.RoundToInt(z/2))]+.08f+peak;var cell=new Vector2Int(Mathf.RoundToInt(x/4),Mathf.RoundToInt(z/4));for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++)if(roadHeight.TryGetValue(cell+new Vector2Int(a,b),out float road))h=Mathf.Min(h,road-.2f);return h;}
static void Capture(Scene scene,Camera c,string name){typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,c.transform.position,c.transform.position+c.transform.forward*800,name});}
static void SnapLine(MeshFilter ring){var data=Read(ring.sharedMesh);var p=Get<Vector3[]>(data,"p").Select(ring.transform.TransformPoint).Select(v=>new Vector2(v.x,v.z)).ToArray();var ids=Get<int[]>(data,"ids");var positions=new List<Vector2>();var weld=new Dictionary<Vector2Int,int>();var remap=new int[p.Length];for(int i=0;i<p.Length;i++){var k=new Vector2Int(Mathf.RoundToInt(p[i].x*100),Mathf.RoundToInt(p[i].y*100));if(!weld.TryGetValue(k,out int index)){index=positions.Count;weld[k]=index;positions.Add(p[i]);}remap[i]=index;}var edges=new Dictionary<Vector2Int,int>();for(int i=0;i<ids.Length;i+=3)for(int j=0;j<3;j++){int a=remap[ids[i+j]],b=remap[ids[i+(j+1)%3]];if(a==b)continue;var key=new Vector2Int(Mathf.Min(a,b),Mathf.Max(a,b));edges[key]=edges.TryGetValue(key,out int n)?n+1:1;}var boundary=edges.Where(v=>v.Value==1).Select(v=>v.Key).ToArray();var result=new List<Vector2>();for(int i=0;i<line.Length-1;i++){int steps=Mathf.CeilToInt(Vector2.Distance(line[i],line[i+1])/8);for(int j=0;j<steps;j++){var target=Vector2.Lerp(line[i],line[i+1],j/(float)steps);float best=float.MaxValue;Vector2 found=target;foreach(var edge in boundary){var a=positions[edge.x];var e=positions[edge.y]-a;var q=a+e*Mathf.Clamp01(Vector2.Dot(target-a,e)/e.sqrMagnitude);float distance=(q-target).sqrMagnitude;if(distance<best){best=distance;found=q;}}if(result.Count==0||Vector2.Distance(result.Last(),found)>2)result.Add(found);}}line=result.ToArray();}
static void Run(){var log=new StringBuilder();try{foundation.Clear();roadHeight.Clear();quads.Clear();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!scene.isLoaded)throw new Exception("Scene not loaded");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var oldGroup=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain");log.AppendLine("Selection: "+(Selection.activeGameObject?Selection.activeGameObject.name:"none"));SnapLine(root.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="polySurface677"));File.WriteAllLines("FinalEnvironmentRoadReview/CoastalSnappedEdge.txt",line.Select(p=>p.ToString("F3")));var outer=new Vector2[line.Length];for(int i=0;i<line.Length;i++){var before=(line[Mathf.Max(0,i)]-line[Mathf.Max(0,i-1)]).normalized;var after=(line[Mathf.Min(line.Length-1,i+1)]-line[i]).normalized;if(before==Vector2.zero)before=after;if(after==Vector2.zero)after=before;var n0=new Vector2(before.y,-before.x);var n1=new Vector2(after.y,-after.x);var normal=(n0+n1).normalized;outer[i]=line[i]+normal*width/Mathf.Max(.75f,Vector2.Dot(normal,n1));}for(int i=0;i<line.Length-1;i++){var q=new[]{line[i],line[i+1],outer[i+1],outer[i]};float area=0;for(int j=0;j<4;j++)area+=q[j].x*q[(j+1)%4].y-q[(j+1)%4].x*q[j].y;if(area<0)Array.Reverse(q);quads.Add(q);}
var originalPrefab=PrefabUtility.LoadPrefabContents("Assets/Editor/CoastalTerrainBackup/Original Roads.prefab");Mesh original;try{original=originalPrefab.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="Outer_MEsh").sharedMesh;}finally{PrefabUtility.UnloadPrefabContents(originalPrefab);}var apron=root.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="Outer_MEsh");var preserved=original;apron.sharedMesh=preserved;foreach(var col in apron.GetComponents<MeshCollider>())col.sharedMesh=preserved;PrefabUtility.RecordPrefabInstancePropertyModifications(apron);
float x0=Mathf.Floor(quads.Min(q=>q.Min(p=>p.x))/4)*4,z0=Mathf.Floor(quads.Min(q=>q.Min(p=>p.y))/4)*4;float sx=Mathf.Ceil((quads.Max(q=>q.Max(p=>p.x))-x0)/4)*4,sz=Mathf.Ceil((quads.Max(q=>q.Max(p=>p.y))-z0)/4)*4;
var probeObject=new GameObject("Original shoreline footprint probe"){hideFlags=HideFlags.HideAndDontSave};probeObject.transform.SetPositionAndRotation(apron.transform.position,apron.transform.rotation);probeObject.transform.localScale=apron.transform.lossyScale;var probe=probeObject.AddComponent<MeshCollider>();probe.sharedMesh=original;for(int z=Mathf.FloorToInt(z0/2)-1;z<=(z0+sz)/2+1;z++)for(int x=Mathf.FloorToInt(x0/2)-1;x<=(x0+sx)/2+1;x++){if(!MaskGeo(x*2,z*2))continue;if(probe.Raycast(new Ray(new Vector3(x*2,140,z*2),Vector3.down),out var hit,210)&&hit.point.y>=25.95f)foundation[new Vector2Int(x,z)]=hit.point.y;}UnityEngine.Object.DestroyImmediate(probeObject);
for(int z=Mathf.CeilToInt(z0/4);z<=(z0+sz)/4;z++)for(int x=Mathf.CeilToInt(x0/4);x<=(x0+sx)/4;x++){if(!Mask(x*4,z*4))continue;var hits=Physics.RaycastAll(new Vector3(x*4,160,z*4),Vector3.down,200,~0,QueryTriggerInteraction.Ignore);foreach(var hit in hits){var r=hit.collider.GetComponent<MeshRenderer>();if(!r||!r.sharedMaterials.Any(m=>m&&(m.name=="Road Atlas"||m.name.StartsWith("City PNG"))))continue;var key=new Vector2Int(x,z);if(!roadHeight.TryGetValue(key,out float previous)||hit.point.y<previous)roadHeight[key]=hit.point.y;}}
UnityEngine.Object.DestroyImmediate(oldGroup);var group=new GameObject("Coastal Rocky Terrain");SceneManager.MoveGameObjectToScene(group,scene);var data=AssetDatabase.LoadAssetAtPath<TerrainData>(Dir+"/Marked Coastal Terrain.asset");if(!data){data=new TerrainData{name="Red marked coastal strip",heightmapResolution=513,alphamapResolution=512,baseMapResolution=1024};AssetDatabase.CreateAsset(data,Dir+"/Marked Coastal Terrain.asset");}data.size=new Vector3(sx,85,sz);data.terrainLayers=new[]{AssetDatabase.LoadAssetAtPath<TerrainLayer>(Dir+"/Coastal Grey Rock.terrainlayer"),AssetDatabase.LoadAssetAtPath<TerrainLayer>(Dir+"/Coastal Grass.terrainlayer")};var heights=new float[513,513];var holes=new bool[512,512];float highest=0;int cells=0;
for(int z=0;z<513;z++)for(int x=0;x<513;x++){float wx=x0+x/512f*sx,wz=z0+z/512f*sz;float h=H(wx,wz);heights[z,x]=h/85;highest=Mathf.Max(highest,h);}data.SetHeights(0,0,heights);
for(int z=0;z<512;z++)for(int x=0;x<512;x++){float wx=x0+(x+.5f)/512*sx,wz=z0+(z+.5f)/512*sz;holes[z,x]=Mask(wx,wz);if(holes[z,x])cells++;}data.SetHoles(0,0,holes);
var alpha=new float[512,512,2];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float wx=x0+(x+.5f)/512*sx,wz=z0+(z+.5f)/512*sz;float slope=new Vector2(H(wx+1,wz)-H(wx-1,wz),H(wx,wz+1)-H(wx,wz-1)).magnitude/2;float patch=Mathf.PerlinNoise(wx/11+47,wz/11+31);float grass=Mathf.Clamp01((1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.9f,2.5f,slope)))*Mathf.Lerp(.25f,.95f,patch));alpha[z,x,1]=grass;alpha[z,x,0]=1-grass;}data.SetAlphamaps(0,0,alpha);data.SetBaseMapDirty();EditorUtility.SetDirty(data);
var go=Terrain.CreateTerrainGameObject(data);go.name="Marked roadside rocky terrain";go.transform.SetParent(group.transform,false);go.transform.position=new Vector3(x0,0,z0);var terrain=go.GetComponent<Terrain>();terrain.materialTemplate=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/Mobile Coastal Terrain.mat");var coastalShader=AssetDatabase.LoadAssetAtPath<Shader>(Dir+"/MobileCoastalTerrain.shader");if(ShaderUtil.GetShaderMessages(coastalShader).Any(v=>v.severity.ToString()=="Error"))throw new Exception("Terrain shader errors");terrain.materialTemplate.shader=coastalShader;terrain.materialTemplate.DisableKeyword("_TERRAIN_INSTANCED_PERPIXEL_NORMAL");terrain.materialTemplate.SetFloat("_TerrainInstancedPerPixelNormal",0);EditorUtility.SetDirty(terrain.materialTemplate);terrain.drawInstanced=true;terrain.heightmapPixelError=10;terrain.heightmapMaximumLOD=1;terrain.basemapDistance=1800;terrain.drawTreesAndFoliage=false;terrain.detailObjectDistance=0;terrain.treeDistance=0;terrain.Flush();terrain.UpdateGIMaterials();
var prefabPath=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(root);var pref=PrefabUtility.LoadPrefabContents(prefabPath);try{var f=pref.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name=="Outer_MEsh");f.sharedMesh=preserved;foreach(var c in f.GetComponents<MeshCollider>())c.sharedMesh=preserved;PrefabUtility.SaveAsPrefabAsset(pref,prefabPath);}finally{PrefabUtility.UnloadPrefabContents(pref);}PrefabUtility.SaveAsPrefabAssetAndConnect(group,Dir+"/Coastal Rocky Terrain.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Capture(scene,SceneView.lastActiveSceneView.camera,"Marked-Coastal-Terrain-Overview");
var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=controller.IsNight;try{controller.ApplyDay();var target=new Vector3(864,40,250);typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,target+new Vector3(50,60,55),target,"Marked-Coastal-Terrain-Detail"});typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Marked-Coastal-Terrain-Road-Level"});}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);log.AppendLine("SUCCESS: one editable Terrain limited to red marked roadside strip; width=45m; 513 heightmap, maxLOD1; shared rock/grass layers; GPU instanced; streamed ASTC textures; no trees/details/new roads/port; original shoreline fully restored; footprint trimmed to existing land; triplanar cliff texturing; road safety samples="+roadHeight.Count+"; active cells="+cells+"; highest="+highest+"; saved scene and prefabs.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalTerrainScopeReport.txt",log.ToString());}}
